const price = Math.round(Number(row.base_rate_cad) * Number(row.tier_multiplier) * 100) / 100;
return [{ json: { price, currency: 'CAD', zone: row.zone, found: 'true', zone_basis: z.basis, pickup_zone: z.pickup_zone, dropoff_zone: z.dropoff_zone, pickup_km: z.pickup_km, dropoff_km: z.dropoff_km }, pairedItem: { item: 0 } }];

