return [{ json: { success: isError ? 'false' : 'true', order_id: isError ? null : row.order_number, confirmation_message: msg, error: errMsg } }];

const rows = $input.all();
const found = rows.length > 0 && !!rows[0].json && !!rows[0].json.status;
if (!found) {
    return [{ json: { found: 'false', status: 'not_found', eta: 'No matching order found' } }];
}
const row = rows[0].json;
const statusMap = {
    pending: 'not yet picked up',
    quoted: 'not yet picked up',
    confirmed: 'not yet picked up',
    in_transit: 'on the way, estimated within a few hours',
    delivered: row.actual_delivery_timestamp ? ('delivered on ' + row.actual_delivery_timestamp) : 'delivered',
    cancelled: 'cancelled'
};
const eta = statusMap[row.status] || 'status unknown';
return [{ json: { found: 'true', status: row.status, eta: eta } }];

const q = $input.first().json.query;
const mode = q ? q['hub.mode'] : undefined;
const token = q ? q['hub.verify_token'] : undefined;
const challenge = q ? (q['hub.challenge'] || '') : '';
const expected = 'nexordis_acme_wa_verify_2026';
const verified = mode === 'subscribe' && token === expected;
return [{json: {verified: verified, challenge: challenge}}];

const body = $input.first().json.body;
const entry = (body.entry && body.entry[0]) || {};
const change = (entry.changes && entry.changes[0]) || {};
const value = change.value || {};
const messages = value.messages || [];
const statuses = value.statuses || [];
const isStatus = messages.length === 0 && statuses.length > 0;
const msg = messages[0] || {};
const from = msg.from || '';
let text = (msg.text && msg.text.body) || '';
let isListSelection = false;
let listSelectionId = '';
if (msg.type === 'interactive' && msg.interactive && msg.interactive.list_reply) {
  isListSelection = true;
  listSelectionId = msg.interactive.list_reply.id || '';
  const menuTextMap = {
    menu_quote: "I'd like to get a quote for a delivery.",
    menu_book: "I'd like to book a delivery.",
    menu_track: "I'd like to track an order.",
    menu_faq: "I have a general question about your service."
  };
  text = menuTextMap[listSelectionId] || (msg.interactive.list_reply.title || '');
}
return [{json: {isStatus: isStatus, from: from, text: text, isListSelection: isListSelection, listSelectionId: listSelectionId}}];

