const from = $('Normalize Conversation Context').first().json.from;
const answer = (result.content && result.content.parts && result.content.parts[0] && result.content.parts[0].text) || result.text || result.output || (result.candidates && result.candidates[0] && result.candidates[0].content && result.candidates[0].content.parts && result.candidates[0].content.parts[0] && result.candidates[0].content.parts[0].text) || 'Thanks for reaching out! A team member will follow up with you shortly.';
return [{json: {from: from, reply_text: answer}}];

