let e = {};
try { e = $('Enforce Required Fields').first().json; } catch (err) { e = {}; }
let reply = String(e.reply_text || '').trim();
if (!reply) { try { reply = String($('Parse Gemini Response').first().json.reply_text || '').trim(); } catch (err) {} }
if (!reply) reply = 'Could you tell me a bit more so I can help with your delivery?';
