const names = ['Format Quote Reply','Format Booking Reply','Format Booking Failed Reply','Format Status Reply', 'Format Cancel Reply','Format FAQ Reply (Direct)', 'Format FAQ Reply','Format Clarifying Reply','Format Off-Topic Reply','Format Welcome Reply'];
