const from = $json.from;
const reply = 'Welcome to Acme Courier Co.! I can help you get a quote, book a delivery, track an order, or answer questions about our service. Choose an option below, or just tell me what you need.';
return [{json: {from: from, reply_text: reply}}];

// Merge the knowledge base into the conversation context so the classifier can answer FAQs in the same call.
// Also: if the conversation has been idle > 30 min, start fresh (don't reuse old package/address/tier).
const base = $('Normalize Conversation Context').first().json;
let conv = {};
try { conv = ($('Get Conversation State').first() || {}).json || {}; } catch (e) { conv = {}; }
const ageMin = conv.updated_at ? (Date.now() - new Date(conv.updated_at).getTime()) / 60000 : 0;
const stale = ageMin > 30;
const priorSlotsJson = stale ? '{}' : base.priorSlotsJson;
const priorIntent = stale ? '' : base.priorIntent;
const docs = $input.all().map(i => i.json).filter(d => d && d.content && d.is_active !== false);
const knowledge_context = docs.length
  ? docs.map(d => '### ' + (d.title || 'Info') + '\n' + d.content).join('\n\n')
  : '(knowledge base unavailable)';
const last_bot_reply = stale ? '' : String(conv.last_bot_reply || '');
const last_order_number = String(conv.last_order_number || '');
return [{ json: { ...base, priorSlotsJson, priorIntent, conversation_stale: stale, last_bot_reply, last_order_number, knowledge_context }, pairedItem: { item: 0 } }];

// FAQ answer now comes straight from the classifier's reply_text (knowledge base was in its prompt).
const from = $('Normalize Conversation Context').first().json.from;
return $input.all().map((i, idx) => ({ pairedItem: { item: idx }, json: { from, reply_text: i.json.reply_text || "Thanks for your question! Let me check with the team and get back to you shortly." } }));

// Deterministic safety net on top of the AI: normalise field values and never let a quote/booking
// go ahead with missing or invalid details, whatever the model said.
const sizes = ['S', 'M', 'L', 'XL'];
const tiers = ['same_day_standard', 'same_day_express', 'next_day'];
const has = v => String(v == null ? '' : v).trim() !== '';
return $input.all().map((item, idx) => {
  const j = { ...item.json };
  const size = String(j.package_size || '').trim().toUpperCase();
  j.package_size = sizes.includes(size) ? size : '';
  const tier = String(j.service_tier || '').trim().toLowerCase();
  j.service_tier = tiers.includes(tier) ? tier : '';
  // Context from this turn (sender number, raw text, previous intent)
  let ctx = {};
  try { ctx = $('Build KB for Classifier').first().json; } catch (err) { ctx = {}; }
  if (!has(j.customer_phone) && has(ctx.from)) j.customer_phone = String(ctx.from);
  // If we just asked for a name to book and the customer replied with only a name, keep booking.
  const msg = String(ctx.text || '').trim();
  const looksLikeName = /^[A-Za-z][A-Za-z .'-]{1,40}$/.test(msg) && msg.split(/\s+/).length <= 4 && !/^(hi|hey|hello|thanks|thank you|ok|okay|yes|no|book|cancel|stop)$/i.test(msg);
  if (j.intent === 'other' && ctx.priorIntent === 'book' && !has(j.customer_name) && looksLikeName) { j.intent = 'book'; j.customer_name = msg; }
  if (j.intent === 'status' && !has(j.order_reference) && has(ctx.last_order_number)) j.order_reference = String(ctx.last_order_number);
  // Cancellation: a plain "yes" right after our cancellation question confirms it (never trust the model alone).
  const askedToConfirmCancel = /reply yes to confirm the cancellation/i.test(String(ctx.last_bot_reply || ''));
  const saidYes = /^(yes|y|yes please|yeah|yep|yup|confirm|confirmed|go ahead|do it|ok|okay|sure|haan|han|ji)\b/i.test(msg);
  if (askedToConfirmCancel && saidYes) {
    const m = String(ctx.last_bot_reply).match(/Order\s+([0-9A-Za-z-]+)/i);
    j.intent = 'cancel'; if (m) j.order_reference = m[1];
  }
  if (j.intent === 'cancel') {
    j.cancel_confirmed = askedToConfirmCancel && saidYes;
    if (!has(j.order_reference) && has(ctx.last_order_number)) j.order_reference = String(ctx.last_order_number);
  }
  const em = String(j.customer_email || '').trim().toLowerCase();
  j.customer_email = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(em) ? em : '';
  // Optional email before booking: ask once, then book whatever the answer ("skip", "no", or an address).
  const lastReply = String(ctx.last_bot_reply || '');
  const askedEmail = /confirmation by email/i.test(lastReply);
  const emailInMsg = (msg.match(/[^\s@]+@[^\s@]+\.[a-z]{2,}/i) || [])[0];
  if (!j.customer_email && emailInMsg) j.customer_email = emailInMsg.toLowerCase();
  if (askedEmail && ctx.priorIntent === 'book' && j.intent !== 'cancel' && j.intent !== 'status') {
    j.intent = 'book';
    let prior = {};
    try { let s = ctx.priorSlotsJson; while (typeof s === 'string') s = JSON.parse(s); prior = s || {}; } catch (err) { prior = {}; }
    for (const k of ['package_size', 'service_tier', 'pickup_address', 'dropoff_address', 'customer_name']) if (!has(j[k]) && has(prior[k])) j[k] = prior[k];
    if (j.package_size) j.package_size = String(j.package_size).toUpperCase();
  }
  // Booking confirmation: a YES right after our booking summary books it (details re-applied from memory).
  const askedConfirmBooking = /reply yes to confirm the booking/i.test(lastReply);
  const saidYesBook = /^(yes|y|yes please|yeah|yep|yup|confirm|confirmed|correct|go ahead|book it|do it|ok|okay|sure|haan|han|ji)\b/i.test(msg);
  if (askedConfirmBooking && saidYesBook) {
    j.intent = 'book';
    j.booking_confirmed = true;
    let priorB = {};
    try { let s = ctx.priorSlotsJson; while (typeof s === 'string') s = JSON.parse(s); priorB = s || {}; } catch (err) { priorB = {}; }
    for (const k of ['package_size', 'service_tier', 'pickup_address', 'dropoff_address', 'customer_name', 'customer_email']) if (!has(j[k]) && has(priorB[k])) j[k] = priorB[k];
    if (j.package_size) j.package_size = String(j.package_size).toUpperCase();
  } else if (askedConfirmBooking && !['cancel', 'status', 'faq'].includes(j.intent)) {
    // A change requested at the summary ("make it express", "different address"): keep booking, re-summarise.
    j.intent = 'book';
    let priorC = {};
    try { let s = ctx.priorSlotsJson; while (typeof s === 'string') s = JSON.parse(s); priorC = s || {}; } catch (err) { priorC = {}; }
    for (const k of ['package_size', 'service_tier', 'pickup_address', 'dropoff_address', 'customer_name', 'customer_email']) if (!has(j[k]) && has(priorC[k])) j[k] = priorC[k];
    if (j.package_size) j.package_size = String(j.package_size).toUpperCase();
  }
  const missing = [];
  if (j.intent === 'quote' || j.intent === 'book') {
    if (!j.package_size) missing.push('the package size (small, medium, large or extra-large)');
    if (!has(j.pickup_address)) missing.push('the pickup address');
    if (!has(j.dropoff_address)) missing.push('the drop-off address');
    if (!j.service_tier) missing.push('which service you would like (Same-Day Standard, Same-Day Express or Next-Day)');
  }
  if (j.intent === 'book' && !has(j.customer_name)) missing.push('the name to put on the booking');
  if ((j.intent === 'status' || j.intent === 'cancel') && !has(j.order_reference)) missing.push('your order number (the confirmation number from your booking)');
  j.missing_fields = missing;
  const ask = () => (j.intent === 'status' ? 'Sure, I can check that for you! Could you share ' : 'Almost there! Could you share ') + (missing.length === 1 ? missing[0] : missing.slice(0, -1).join(', ') + ' and ' + missing[missing.length - 1]) + '?';
  if (j.intent === 'quote' || j.intent === 'book' || j.intent === 'status' || j.intent === 'cancel') {
    // Readiness is decided by the data, not the model: go ahead exactly when nothing is missing.
    if (missing.length) {
      if (j.ready_to_proceed === true || !has(j.reply_text)) j.reply_text = ask();
      j.ready_to_proceed = false;
    } else {
      j.ready_to_proceed = true;
    }
  }
  if (j.intent === 'book' && j.ready_to_proceed === true && !j.customer_email && !askedEmail && !askedConfirmBooking && !j.booking_confirmed) {
    const first = String(j.customer_name || '').trim().split(/\s+/)[0];
    j.ready_to_proceed = false;
    j.reply_text = 'Almost done' + (first ? ', ' + first : '') + '! Would you like a confirmation by email? Just share your email address, or reply "skip" to book without it.';
  }
  // Everything collected but not yet confirmed: show a summary with the price (quote route) and ask for YES.
  if (j.intent === 'book' && j.ready_to_proceed === true && !j.booking_confirmed) {
    j.intent = 'quote';
    j.book_pending = true;
  }
  if (j.ready_to_proceed !== true && !has(j.reply_text)) {
    j.reply_text = missing.length ? 'Could you share ' + missing.join(', ') + '?' : 'How can I help you today? I can give you a quote, book a delivery, track an order or answer questions.';
  }
  return { json: j, pairedItem: { item: idx } };
});

// Runs after an order is saved (WhatsApp or voice). Builds the HubSpot contact + deal. Test numbers (999...) are skipped.
const norm = v => { let d = String(v || '').replace(/\D/g, ''); if (d.length === 10) d = '1' + d; return d; };
const row = $input.first().json;
if (!row || row.error || !row.order_number) return [];
const phone = norm(row.customer_phone);
if (!phone || phone.startsWith('999')) return [];
const channel = row.intake_channel === 'whatsapp' ? 'WhatsApp' : 'Voice';
const name = String(row.customer_name || '').trim();
const parts = name.split(/\s+/).filter(Boolean);
const sizeNames = { S: 'Small', M: 'Medium', L: 'Large', XL: 'Extra-large' };
const tierNames = { same_day_standard: 'Same-Day Standard', same_day_express: 'Same-Day Express', next_day: 'Next-Day' };
const contactProps = { acme_customer_phone: phone, phone: '+' + phone, acme_last_channel: channel };
if (parts.length) { contactProps.firstname = parts[0]; if (parts.length > 1) contactProps.lastname = parts.slice(1).join(' '); }
const deal = { idProperty: 'acme_order_number', id: String(row.order_number), properties: {
  acme_order_number: String(row.order_number),
  dealname: 'Order ' + row.order_number + ' · ' + (sizeNames[row.package_size] || row.package_size || '') + ' · ' + (tierNames[row.service_tier] || row.service_tier || ''),
  amount: row.quoted_price_cad != null ? String(row.quoted_price_cad) : '',
  pipeline: 'default', dealstage: ({ quoted: '4359622340', pending: '4359622341', confirmed: '4359622341', in_transit: '4359622342', delivered: '4359622343', cancelled: '4359622344' })[row.status] || '4359622341', closedate: new Date().toISOString(),
  acme_pickup_address: row.pickup_address || '', acme_dropoff_address: row.dropoff_address || '',
  acme_package_size: sizeNames[row.package_size] || row.package_size || '', acme_service_tier: tierNames[row.service_tier] || row.service_tier || '',
  acme_channel: channel } };
return [{ json: { contact: { idProperty: 'acme_customer_phone', id: phone, properties: contactProps }, deal }, pairedItem: { item: 0 } }];

// New WhatsApp conversation -> HubSpot contact (name from the WhatsApp profile, if any). Test numbers skipped.
