// Zone = distance band from the depot (downtown Toronto, M5V), per the KB "Service Area & Coverage".
// The trip is priced on the farther of pickup / drop-off. Outside the GTA = out of area (KB policy).
const DEPOT = { lat: 43.6426, lon: -79.3871 };
const BANDS = [ { zone: 1, km: 4 }, { zone: 2, km: 10 }, { zone: 3, km: 20 }, { zone: 4, km: 50 } ];
const args = $('Webhook - Get Quote').first().json.body.args || {};
const km = (a, b) => { const R = 6371, r = d => d * Math.PI / 180; const dLat = r(b.lat - a.lat), dLon = r(b.lon - a.lon); const h = Math.sin(dLat / 2) ** 2 + Math.cos(r(a.lat)) * Math.cos(r(b.lat)) * Math.sin(dLon / 2) ** 2; return 2 * R * Math.asin(Math.sqrt(h)); };
const hit = n => { try { const j = $(n).first().json; return j && j.lat ? { lat: Number(j.lat), lon: Number(j.lon), label: j.display_name || '' } : null; } catch (e) { return null; } };
// Fallback when an address can't be geocoded: estimate from place names.
const OUT_RE = /usa|u\.s\.|united states|\bny\b|new york|buffalo|detroit|montreal|quebec|vancouver|calgary|edmonton|winnipeg|ottawa|hamilton|niagara|kitchener|waterloo|london,? on|barrie|kingston/i;
