  if (OUT_RE.test(a)) return -1;
  if (/mississauga|brampton|markham|vaughan|richmond hill|pickering|ajax|oakville/.test(a)) return 4;
  if (/scarborough|etobicoke|north york/.test(a)) return 3;
  if (/east york|\byork\b|leaside|the beaches|high park|midtown/.test(a)) return 2;
  if (/\bm5[a-z]/i.test(a)) return 1;
